import { notFound } from "next/navigation";
import {
  getSitemapDirectoryTours,
  SITEMAP_TOURS_PER_PAGE,
} from "@/services/sitemap/directory";
import SitemapShell, { sitemapLinkClass } from "./shell";

export function toursPageHref(page: number): string {
  return page <= 1 ? "/sitemap/tours" : `/sitemap/tours/${page}`;
}

export function toursPageCount(total: number): number {
  return Math.max(1, Math.ceil(total / SITEMAP_TOURS_PER_PAGE));
}

/** Alfabetik, sayfalanmış tur dizini (liste + sayfa numaraları). */
export default async function ToursDirectory({ page }: { page: number }) {
  const data = await getSitemapDirectoryTours(page);
  const totalPages = toursPageCount(data.total);

  if (page > totalPages || data.items.length === 0) notFound();

  const title = page > 1 ? `All Tours — Page ${page}` : "All Tours";

  return (
    <SitemapShell
      title={title}
      intro={`Browse all ${data.total.toLocaleString("en-US")} tours on TravelShop Booking, listed alphabetically.`}
      crumbs={[
        { pageTitle: "Sitemap", pageUrl: "/sitemap" },
        {
          pageTitle: page > 1 ? `Tours — Page ${page}` : "Tours",
          pageUrl: toursPageHref(page),
        },
      ]}
    >
      <ul className="tw-list-none tw-m-0 tw-p-0 tw-columns-1 md:tw-columns-2 tw-gap-x-10 [&>li]:tw-mb-2 [&>li]:tw-break-inside-avoid">
        {data.items.map((tour) => (
          <li key={tour.slug}>
            <a href={`/tour/${tour.slug}`} className={sitemapLinkClass}>
              {tour.name}
            </a>
            {tour.durationDays !== null && tour.durationDays > 0 && (
              <span className="tw-ml-1.5 tw-text-[12px] tw-text-[#9a93a8]">
                · {tour.durationDays} {tour.durationDays === 1 ? "day" : "days"}
              </span>
            )}
          </li>
        ))}
      </ul>

      <nav
        aria-label="Tour directory pages"
        className="tw-mt-10 tw-flex tw-flex-wrap tw-gap-2"
      >
        {Array.from({ length: totalPages }, (_, i) => i + 1).map((n) =>
          n === page ? (
            <span
              key={n}
              aria-current="page"
              className="tw-inline-flex tw-min-w-[36px] tw-justify-center tw-rounded-lg tw-bg-[#854ec9] tw-px-2.5 tw-py-1.5 tw-text-[14px] tw-font-semibold tw-text-white"
            >
              {n}
            </span>
          ) : (
            <a
              key={n}
              href={toursPageHref(n)}
              className="tw-inline-flex tw-min-w-[36px] tw-justify-center tw-rounded-lg tw-border tw-border-solid tw-border-[#ebe7f0] tw-px-2.5 tw-py-1.5 tw-text-[14px] tw-text-[#5d556c] hover:tw-border-[#854ec9] hover:tw-text-[#854ec9] tw-transition-colors tw-no-underline"
            >
              {n}
            </a>
          ),
        )}
      </nav>
    </SitemapShell>
  );
}
