import type { Metadata } from "next";
import { notFound } from "next/navigation";
import ToursDirectory, {
  toursPageCount,
} from "@/components/sitemap-directory/tours-directory";
import { getSitemapDirectoryTours } from "@/services/sitemap/directory";

export const revalidate = 86400;
export const dynamicParams = true;

/** 1. sayfa /sitemap/tours'ta; burada yalnız 2..N ön-üretilir (prod build). */
export async function generateStaticParams() {
  if (process.env.SERVER !== "production") return [];

  const first = await getSitemapDirectoryTours(1);
  const totalPages = toursPageCount(first.total);

  return Array.from({ length: Math.max(0, totalPages - 1) }, (_, i) => ({
    page: String(i + 2),
  }));
}

function parsePage(raw: string): number | null {
  const n = Number(raw);
  return Number.isInteger(n) && n >= 2 ? n : null;
}

export async function generateMetadata({
  params,
}: {
  params: { page: string };
}): Promise<Metadata> {
  const page = parsePage(params.page);
  if (page === null) return {};

  return {
    title: `All Tours Sitemap - Page ${page} - TravelShop Booking`,
    description: `Alphabetical directory of all tours on TravelShop Booking, page ${page}.`,
    alternates: {
      canonical: `https://travelshopbooking.com/sitemap/tours/${page}`,
    },
  };
}

export default function SitemapToursPagedPage({
  params,
}: {
  params: { page: string };
}) {
  const page = parsePage(params.page);
  if (page === null) notFound();

  return <ToursDirectory page={page} />;
}
